def difference(d1, d2, level=-1):
    if level == 0:
        return d1
    diff = {}
    for key, value in d1.items():
        if key not in d2:
            diff[key] = value
        elif value != d2[key]:
            if level == -1 or isinstance(value, dict):
                diff[key] = difference(value, d2[key], level-1)
            else:
                diff[key] = value
    return diff

