def absorb(self, args):
    result = []
    for expr in args:
        if expr.op == '|' and expr.left == expr.right:
            result.append(expr.left)
        elif expr.op == '&' and expr.left == ~expr.right:
            result.append(expr.left)
        elif expr.op == '|' and expr.right == ~expr.left:
            result.append(expr.right)
        elif expr.op == '&' and expr.right == ~expr.left:
            result.append(expr.right)
        else:
            result.append(expr)
    return result

