def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")

    if number == 0:
        return alphabet[0]

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        digits = digits + [alphabet[0]] * padding

    return "".join(reversed(digits))

def split(s, platform='this'):
    """
    Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = os.name

    if platform == 'posix':
        return shlex.split(s)
    elif platform == 'nt':
        return shlex.split(s, posix=False)
    else:
        raise ValueError("Invalid platform specified")

Note: The `shlex.split()` function is used to split a string into a list of arguments, using the same rules as the Unix shell. The `posix` parameter is set to `False` for the Windows platform, to use the Windows command-line syntax instead of the POSIX syntax.

