def popitem(self):
    if not self.data:
        raise KeyError("popitem(): dictionary is empty")

    min_count = min(self.data.values())
    for key, count in self.data.items():
        if count == min_count:
            del self.data[key]
            return key, min_count

    raise ValueError("popitem(): unable to find the least frequently used item")

